#!/usr/bin/env node
// Writes (sync) or verifies (check) the app's generated legal version file
// from its `legal` submodule, so the commit the app links to, the commit the
// Dockerfile's fallback clone checks out and the documents it serves can never
// drift apart.
//
//   kaperkunde-legal sync     # write the file
//   kaperkunde-legal check    # fail if it is out of date
//
// Reads legal.config.json from the working directory:
//
//   {
//     "submodule": "legal",                 // where the submodule sits (default)
//     "out": "lib/legal/version.ts",        // the generated file (default)
//     "witness": "pcpgg/privacy.md",        // a file that proves it is checked out
//     "blobs": ["pcpgg/terms.md"],          // optional: blob SHAs to verify at boot
//     "tracked": { "HOSTING_TOS": "hosting/tos.md" }
//                                           // optional: <KEY>_COMMIT, the last commit
//                                           // that changed the file, and <KEY>_BLOB_SHA
//   }
//
// The build cannot do this itself (.dockerignore keeps .git out of the
// image), hence a generated file committed with every pointer bump.

import { createHash } from "node:crypto"
import { execFileSync } from "node:child_process"
import { existsSync, readFileSync, writeFileSync } from "node:fs"
import { join } from "node:path"

const root = process.cwd()
const mode = process.argv[2]

if (mode !== "sync" && mode !== "check") {
  console.error("usage: kaperkunde-legal sync|check")
  process.exit(2)
}

const configPath = join(root, "legal.config.json")
if (!existsSync(configPath)) {
  console.error(`kaperkunde-legal: ${configPath} is missing.`)
  process.exit(2)
}

const config = JSON.parse(readFileSync(configPath, "utf8"))
const submodule = config.submodule ?? "legal"
const out = config.out ?? "lib/legal/version.ts"
const blobs = config.blobs ?? []
const tracked = config.tracked ?? {}

function git(args, cwd = root) {
  try {
    return execFileSync("git", args, {
      cwd,
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
    }).trim()
  } catch {
    return null
  }
}

const SHA = /^[0-9a-f]{40}$/

/**
 * The commit the submodule is pinned to: its own checkout when it has one
 * (what this build actually serves), else the gitlink in the index, which is
 * what a CI checkout without submodules still knows.
 */
function pinnedCommit() {
  if (existsSync(join(root, submodule, ".git"))) {
    const head = git(["-C", submodule, "rev-parse", "HEAD"])
    if (head && SHA.test(head)) return head
  }
  const gitlink = git(["ls-files", "-s", submodule])
  const match = gitlink?.match(/^160000 ([0-9a-f]{40})/)
  return match ? match[1] : null
}

function blobSha(file) {
  const bytes = readFileSync(join(root, submodule, file))
  return createHash("sha1")
    .update(`blob ${bytes.length}\0`)
    .update(bytes)
    .digest("hex")
}

function fail(message) {
  console.error(`kaperkunde-legal: ${message}`)
  process.exit(1)
}

const commit = pinnedCommit()
if (!commit) {
  fail(
    "could not resolve the submodule commit. Run `git submodule update --init legal` first.",
  )
}

for (const file of [config.witness, ...blobs, ...Object.values(tracked)].filter(
  Boolean,
)) {
  if (!existsSync(join(root, submodule, file))) {
    fail(
      `${submodule}/${file} is missing. Run \`git submodule update --init legal\` first.`,
    )
  }
}

const lines = [
  "// Generated by kaperkunde-legal (@kaperkunde/legal) — do not edit by hand.",
  "// Run `kaperkunde-legal sync` whenever the `legal` submodule pointer moves,",
  "// and commit this file with the pointer bump; `kaperkunde-legal check` fails",
  "// when the two disagree.",
  "",
  "/** Commit of the `legal` submodule this build serves, and what the Dockerfile's fallback clone checks out. */",
  `export const LEGAL_COMMIT = "${commit}"`,
]

if (blobs.length > 0) {
  lines.push(
    "",
    "/** git blob SHAs of the served documents, checked at boot (getLegalDocsProblem). */",
    "export const LEGAL_BLOB_SHAS: Readonly<Record<string, string>> = {",
    ...blobs.map((file) => `  ${JSON.stringify(file)}: "${blobSha(file)}",`),
    "}",
  )
}

for (const [key, file] of Object.entries(tracked)) {
  const last = git(["-C", submodule, "log", "-1", "--format=%H", "--", file])
  if (!last || !SHA.test(last)) {
    fail(
      `could not find the last commit touching ${submodule}/${file}. This needs ` +
        "the submodule's history: run `git submodule update --init legal`, and in CI " +
        "set `fetch-depth: 0` on actions/checkout.",
    )
  }
  lines.push(
    "",
    `/** The last commit that changed ${file}. */`,
    `export const ${key}_COMMIT = "${last}"`,
    "",
    `/** git blob SHA of ${file} as shipped. */`,
    `export const ${key}_BLOB_SHA = "${blobSha(file)}"`,
  )
}

const next = `${lines.join("\n")}\n`
const outPath = join(root, out)
const current = existsSync(outPath) ? readFileSync(outPath, "utf8") : null

if (current === next) {
  console.log(`${out} is up to date (${commit}).`)
  process.exit(0)
}

if (mode === "check") {
  fail(
    `${out} is out of date with the \`legal\` submodule (${commit}). Run \`kaperkunde-legal sync\` and commit the result.`,
  )
}

writeFileSync(outPath, next)
console.log(`Wrote ${out} (${commit}).`)
